namespace Wisk.App;

public sealed record UiLanguage(string Code, string NativeName, FlowDirection Direction)
{
    public override string ToString() => NativeName;
}

[MarkupExtensionReturnType(typeof(object))]
public sealed class LocExtension(string key) : MarkupExtension
{
    public string Key { get; } = key;

    public override object ProvideValue(IServiceProvider serviceProvider) =>
        new Binding($"[{Key}]") { Source = LocalizedText.Instance, Mode = BindingMode.OneWay }
            .ProvideValue(serviceProvider);
}

public sealed class LocalizedText : INotifyPropertyChanged
{
    public static LocalizedText Instance { get; } = new();
    public string this[string key] => Localization.Get(key);
    public event PropertyChangedEventHandler? PropertyChanged;
    internal void Refresh() => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
}

