    private static readonly Dictionary<string, string> KeyByEnglish = Text["en"]
        .GroupBy(pair => pair.Value, StringComparer.OrdinalIgnoreCase)
        .ToDictionary(group => group.Key, group => group.First().Key, StringComparer.OrdinalIgnoreCase);
    public static string CurrentCode { get; private set; } = "en";
    public static string Get(string key) => Get(key, CurrentCode);
    public static string Get(string key, string code) => Text.TryGetValue(code, out var values) && values.TryGetValue(key, out var value) ? value : Text["en"].GetValueOrDefault(key, key);
    public static string Format(string key, params object?[] arguments) => string.Format(Get(key), arguments);
    public static IReadOnlyList<string> MissingTranslationKeys(string code) =>
        !Text.TryGetValue(code, out var values) ? Text["en"].Keys.OrderBy(key => key).ToArray() :
        Text["en"].Keys.Where(key => !values.ContainsKey(key)).OrderBy(key => key).ToArray();
    public static bool ContainsKey(string key) => Text["en"].ContainsKey(key);

    public static string Translate(string value)
    {
        if (string.IsNullOrWhiteSpace(value)) return value;
        var key = KeyByEnglish.TryGetValue(value, out var englishKey) ? englishKey : Text.Values.SelectMany(values => values).FirstOrDefault(pair => pair.Value.Equals(value, StringComparison.OrdinalIgnoreCase)).Key;
        return key is null ? value : Get(key);
    }

    public static void Apply(MainWindow window, string code)
    {
        CurrentCode = Languages.Any(language => language.Code.Equals(code, StringComparison.OrdinalIgnoreCase)) ? code : "en";
        LocalizedText.Instance.Refresh();
        System.Diagnostics.Debug.WriteLine($"Localization '{CurrentCode}' missing {MissingTranslationKeys(CurrentCode).Count} key(s).");
        window.FlowDirection = Languages.First(item => item.Code.Equals(CurrentCode, StringComparison.OrdinalIgnoreCase)).Direction;
        window.LanguageCodeChanged(CurrentCode);
    }

    public static void Apply(ConfigurationDialog dialog, string code)
    {
        CurrentCode = Languages.Any(language => language.Code.Equals(code, StringComparison.OrdinalIgnoreCase)) ? code : "en";
        LocalizedText.Instance.Refresh();
        dialog.FlowDirection = Languages.First(item => item.Code.Equals(CurrentCode, StringComparison.OrdinalIgnoreCase)).Direction;
    }
}
